script:
(function () {
  'use strict';
  // Salary / hourly pay conversion (no tax).
  //   Unadjusted annual pay: hourly x hours/week x 52, daily x days/week x 52,
  //     or per-period pay x periods per year (52, 26, 24, 12, 4, 1).
  //   Days worked = 52 x days/week - holidays - vacation days; hours/day = hours/week / days/week.
  //   Adjusted annual pay: for hourly or daily pay, only days worked are paid
  //     (rate x days worked x hours/day, or rate x days worked); salaried pay stays the same
  //     and is spread over fewer hours, which raises the effective hourly rate.
  //   Adjusted per-period amounts = adjusted annual / 52, 26, 24, 12, 4; adjusted hourly and
  //     daily = adjusted annual / hours or days actually worked.
  // Verified (Node, scratch tests): $30/hour, 40 h, 5 days, 10 holidays + 15 vacation ->
  //   $62,400 a year, $5,200 a month, $2,400 bi-weekly, $2,600 semi-monthly; 235 days worked,
  //   adjusted annual $56,400 (30 x 8 x 235). $75,000/year -> $36.06/hour unadjusted,
  //   $39.89/hour adjusted (75,000 / 1,880 h). $2,000 bi-weekly -> $52,000 a year.
  var PERIODS = { week: 52, biweek: 26, semimonth: 24, month: 12, quarter: 4, year: 1 };
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var count = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function convert(amount, unit, hoursPerWeek, daysPerWeek, holidays, vacation) {
    var hoursPerDay = hoursPerWeek / daysPerWeek;
    var annual;
    if (unit === 'hour') annual = amount * hoursPerWeek * 52;
    else if (unit === 'day') annual = amount * daysPerWeek * 52;
    else annual = amount * (PERIODS[unit] || 1);
    var workDays = Math.max(0, 52 * daysPerWeek - holidays - vacation);
    var workHours = workDays * hoursPerDay;
    var adjAnnual = unit === 'hour' ? amount * workHours : unit === 'day' ? amount * workDays : annual;
    function row(label, unadj, adj) { return { label: label, unadj: unadj, adj: adj }; }
    var rows = [
      row('Hourly', annual / (hoursPerWeek * 52), workHours > 0 ? adjAnnual / workHours : NaN),
      row('Daily', annual / (daysPerWeek * 52), workDays > 0 ? adjAnnual / workDays : NaN),
      row('Weekly', annual / 52, adjAnnual / 52),
      row('Bi-weekly', annual / 26, adjAnnual / 26),
      row('Semi-monthly', annual / 24, adjAnnual / 24),
      row('Monthly', annual / 12, adjAnnual / 12),
      row('Quarterly', annual / 4, adjAnnual / 4),
      row('Annual', annual, adjAnnual)
    ];
    return { annual: annual, adjAnnual: adjAnnual, workDays: workDays, workHours: workHours,
             paidHours: hoursPerWeek * 52, rows: rows };
  }

  function fill(rows) {
    var body = document.getElementById('slTable');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (r) {
      var tr = document.createElement('tr');
      var th = document.createElement('th');
      th.setAttribute('scope', 'row');
      th.textContent = r.label;
      tr.appendChild(th);
      [r.unadj, r.adj].forEach(function (v) {
        var td = document.createElement('td');
        td.textContent = isFinite(v) ? money.format(v) : '–';
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['slAnnual', 'slMonthly', 'slHourly', 'slPaidHours', 'slWorkDays', 'slAdjHourly'].forEach(function (id) { set(id, '–'); });
    fill([]);
    var note = document.getElementById('slNote');
    if (note) note.hidden = true;
  }

  function update() {
    var amount = num('slAmount'), hours = num('slHours'), days = num('slDays'),
        holidays = num('slHolidays'), vacation = num('slVacation');
    var unitEl = document.getElementById('slUnit');
    var unit = unitEl ? unitEl.value : 'hour';
    if (unit !== 'hour' && unit !== 'day' && !PERIODS[unit]) unit = 'hour';
    if (isNaN(holidays)) holidays = 0;
    if (isNaN(vacation)) vacation = 0;
    var msg = '';
    if (isNaN(amount) || amount < 0) msg = 'Enter your pay as an amount of zero or more.';
    else if (amount > 1e9) msg = 'Enter a pay amount below $1 billion.';
    else if (isNaN(hours) || hours <= 0 || hours > 168) msg = 'Enter hours per week from 1 to 168.';
    else if (isNaN(days) || days <= 0 || days > 7) msg = 'Enter days per week from 1 to 7.';
    else if (hours / days > 24) msg = 'That works out to more than 24 hours a day. Check your hours and days per week.';
    else if (holidays < 0 || vacation < 0) msg = 'Holidays and vacation days cannot be negative.';
    else if (holidays + vacation >= 52 * days) msg = 'Holidays and vacation add up to more than all your working days in a year.';
    var error = document.getElementById('slError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var r = convert(amount, unit, hours, days, holidays, vacation);
    set('slAnnual', money.format(r.annual));
    set('slMonthly', money.format(r.annual / 12));
    set('slHourly', money.format(r.rows[0].unadj));
    set('slPaidHours', count.format(r.paidHours));
    set('slWorkDays', count.format(r.workDays));
    set('slAdjHourly', money.format(r.rows[0].adj));
    fill(r.rows);
    var note = document.getElementById('slNote');
    if (note) {
      var unpaid = unit === 'hour' || unit === 'day';
      note.hidden = false;
      note.textContent = unpaid
        ? 'If your ' + holidays + ' holidays and ' + vacation + ' vacation days are unpaid, you would earn about ' +
          money.format(r.annual - r.adjAnnual) + ' less a year than the unadjusted figure.'
        : 'On a fixed salary your pay does not change with time off, but you earn ' + money.format(r.rows[0].adj) +
          ' for each hour you actually work once holidays and vacation are taken out.';
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('slForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
